# owner: platform
"""Seating charts: students by last name, cut into rows."""

from typing import List
from rosterkit.models import Student

def _check_seats(
    students: List[Student], per_row: int
) -> None:
    if per_row <= 0:
        raise ValueError(f"bad seat count: {per_row}")
    if not students:
        raise ValueError("no students to seat")

def _by_last_name(student: Student) -> str:
    return student.last_name

def _split_rows(
    students: List[Student], per_row: int
) -> List[List[Student]]:
    ordered = sorted(students, key=_by_last_name)
    starts = range(0, len(ordered), per_row)
    return [ordered[at : at + per_row] for at in starts]

def _format_row(number: int, row: List[Student]) -> str:
    names = " | ".join(item.display_name for item in row)
    return f"Row {number}: {names}"

def _format_rows(rows: List[List[Student]]) -> List[str]:
    lines = []
    for number, row in enumerate(rows, 1):
        lines.append(_format_row(number, row))
    return lines

# ---
def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    _check_seats(students, per_row)
    return _format_rows(_split_rows(students, per_row))
